package vn.com.viettel.vds.aop;

import lombok.extern.slf4j.Slf4j;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Configuration;

/**
 * AOP for logging out slow queries
 *
 * @author thanhnd59
 */
@Aspect
@Configuration
@Slf4j
public class RepositoryAspect {

  @Value("${application.repository.query-limit-warning-ms:1000}")
  private int executionLimitMs;

  @Around("execution(* vn.com.viettel.vds.repository.*.*(..))")
  public Object logExecutionTime(ProceedingJoinPoint joinPoint) throws Throwable {
    long start = System.currentTimeMillis();
    Object proceed = joinPoint.proceed();
    long executionTime = System.currentTimeMillis() - start;
    String message = joinPoint.getSignature() + " exec in " + executionTime + " ms";
    if (executionTime >= executionLimitMs) {
      log.warn(message + " : SLOW QUERY");
    }
    return proceed;
  }
}

package vn.com.viettel.vds.aop;

import lombok.extern.log4j.Log4j2;
import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.reflect.MethodSignature;
import org.springframework.stereotype.Component;
import vn.com.viettel.vds.util.common.ThreadContextManage;

import java.lang.reflect.Method;

@Aspect
@Component
@Log4j2
public class ThreadContextAspect {
    @Around("@annotation(ThreadLocalSpace)")
    public Object processClearThreadLocalContext(ProceedingJoinPoint joinPoint) throws Throwable {
        try {
            return joinPoint.proceed();
        } catch (Exception e) {
            log.error("error process :", e);
            throw e;
        } finally {
            if (this.isClearContext(joinPoint)) {
                ThreadContextManage.getInstance().clear();
            }
        }
    }

    private boolean isClearContext(ProceedingJoinPoint proceedingJoinPoint) {
        return this.getAnnotationThreadLocalSpaceOfMethod(proceedingJoinPoint).isClearContext();
    }

    private ThreadLocalSpace getAnnotationThreadLocalSpaceOfMethod(ProceedingJoinPoint proceedingJoinPoint) {
        MethodSignature methodSignature = (MethodSignature) proceedingJoinPoint.getSignature();
        Method method = methodSignature.getMethod();
        return method.getAnnotation(ThreadLocalSpace.class);
    }
}

package vn.com.viettel.vds.aop;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface ThreadLocalSpace {
    boolean isClearContext() default true;
}

