package vn.com.viettel.vds.config;

import java.util.ArrayList;
import java.util.List;
import java.util.TimeZone;
import javax.annotation.PostConstruct;

import lombok.Getter;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.filter.CharacterEncodingFilter;
import vn.com.viettel.vds.filter.message.AccumulationFilter;
import vn.com.viettel.vds.filter.message.CommonValidationFilter;
import vn.com.viettel.vds.filter.message.ServiceFilter;
import vn.com.viettel.vds.filter.message.TransDailyHisFinanceMessageFilter;

@Configuration
@Getter
public class AppConfig {

  /**
   * applicationShortName Type String
   */
  @Value("${application-short-name:policy-data-process}")
  private String applicationShortName;

  @Value("${policy.redis-key}")
  private String redisKey;

  @Value("${policy.redis-prefix-key:policy-payment-fee}")
  private String redisPrefixKey;

  @Value("${app.cache.redisson.cacheExpirations.AccumulateLimit:90000}")
  private long accumulateLimit;

  @Value("${app.cache.redisson.cacheExpirations.CustomerPaymentAccumulation:90000}")
  private int customerPaymentAccumulation;

  @Value("${app.system:''}")
  private String system;


  @PostConstruct
  void started() {
    TimeZone.setDefault(TimeZone.getTimeZone("Asia/Ho_Chi_Minh"));
  }

  @Bean
  CharacterEncodingFilter characterEncodingFilter() {
    CharacterEncodingFilter filter = new CharacterEncodingFilter();
    filter.setEncoding("UTF-8");
    filter.setForceEncoding(true);
    return filter;
  }

  @Bean
  List<TransDailyHisFinanceMessageFilter> transDailyHisFinanceMessageFilter(
      CommonValidationFilter commonValidationFilter, ServiceFilter serviceFilter,
      AccumulationFilter accumulationFilter) {
    //filter chain
    List<TransDailyHisFinanceMessageFilter> filters = new ArrayList<>();
    filters.add(commonValidationFilter);
    filters.add(serviceFilter);
    filters.add(accumulationFilter);
    return filters;
  }

  public String getLimitCode(String code, String transType) {
    if ("VTM".equals(system) && "OUT".equals(transType)) return code;
    return code.concat("_".concat(transType));
  }
}

package vn.com.viettel.vds.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.task.TaskExecutor;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@Configuration
@EnableAsync
public class AsyncConfiguration {
  @Value("20")
  private int corePoolSize;

  @Value("50")
  private int maxPoolSize;

  @Value("10000")
  private int queueCapacity;

  @Bean(name = "threadPoolTaskExecutor")
  public TaskExecutor getAsyncExecutor() {
    return asyncExecutor("async-thread");
  }

  public TaskExecutor asyncExecutor(String threadNamePrefix) {
    ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
    executor.setCorePoolSize(corePoolSize);
    executor.setMaxPoolSize(maxPoolSize);
    executor.setQueueCapacity(queueCapacity);
    executor.setWaitForTasksToCompleteOnShutdown(true);
    executor.setThreadNamePrefix(threadNamePrefix);
    executor.initialize();
    return executor;
  }
}

