package vn.com.viettel.vds.config.database;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import javax.sql.DataSource;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.springframework.boot.jdbc.DatabaseDriver;
import org.springframework.jdbc.support.JdbcUtils;
import org.springframework.jdbc.support.MetaDataAccessException;
import org.springframework.orm.jpa.vendor.Database;

final class DatabaseLookup {

  private static final Log logger = LogFactory.getLog(DatabaseLookup.class);

  private static final Map<DatabaseDriver, Database> LOOKUP;

  static {
    Map<DatabaseDriver, Database> map = new EnumMap<>(DatabaseDriver.class);
    map.put(DatabaseDriver.DERBY, Database.DERBY);
    map.put(DatabaseDriver.H2, Database.H2);
    map.put(DatabaseDriver.HSQLDB, Database.HSQL);
    map.put(DatabaseDriver.MYSQL, Database.MYSQL);
    map.put(DatabaseDriver.ORACLE, Database.ORACLE);
    map.put(DatabaseDriver.POSTGRESQL, Database.POSTGRESQL);
    map.put(DatabaseDriver.SQLSERVER, Database.SQL_SERVER);
    map.put(DatabaseDriver.DB2, Database.DB2);
    map.put(DatabaseDriver.INFORMIX, Database.INFORMIX);
    map.put(DatabaseDriver.HANA, Database.HANA);
    map.put(DatabaseDriver.MARIADB, Database.MYSQL);
    LOOKUP = Collections.unmodifiableMap(map);
  }

  private DatabaseLookup() {
  }

  /**
   * Return the most suitable {@link Database} for the given {@link DataSource}.
   *
   * @param dataSource the source {@link DataSource}
   * @return the most suitable {@link Database}
   */
  static Database getDatabase(DataSource dataSource) {
    if (dataSource == null) {
      return Database.DEFAULT;
    }
    try {
      String url = JdbcUtils.extractDatabaseMetaData(dataSource, "getURL");
      DatabaseDriver driver = DatabaseDriver.fromJdbcUrl(url);
      Database database = LOOKUP.get(driver);
      if (database != null) {
        return database;
      }
    } catch (MetaDataAccessException ex) {
      logger.warn("Unable to determine jdbc url from datasource", ex);
    }
    return Database.DEFAULT;
  }

}

package vn.com.viettel.vds.config.database;

import com.zaxxer.hikari.HikariDataSource;
import javax.persistence.EntityManagerFactory;
import javax.sql.DataSource;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.autoconfigure.jdbc.DataSourceProperties;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.boot.orm.jpa.EntityManagerFactoryBuilder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.springframework.core.env.Environment;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.orm.jpa.JpaTransactionManager;
import org.springframework.orm.jpa.LocalContainerEntityManagerFactoryBean;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;

@Configuration
@ConditionalOnProperty(value = "app.datasource.main.enabled", havingValue = "true", matchIfMissing = true)
@EnableTransactionManagement
@EnableJpaRepositories(
    entityManagerFactoryRef = "mainEntityManagerFactory",
    transactionManagerRef = "mainTransactionManager",
    basePackages = {"vn.com.viettel.vds.repository.main"})
@EnableConfigurationProperties(MainJpaProperties.class)
public class MainDatabaseConfig {

  @Autowired
  private Environment env;

  @Bean
  @Primary
  @ConfigurationProperties("app.datasource.main")
  public DataSourceProperties defaultDataSourceProperties() {
    return new DataSourceProperties();
  }

  @Primary
  @Bean(name = "mainDataSource")
  @ConfigurationProperties(prefix = "app.datasource.main.hikari")
  public DataSource dataSource() {
    return defaultDataSourceProperties().initializeDataSourceBuilder().type(HikariDataSource.class)
        .build();
  }

  @Primary
  @Bean(name = "mainEntityManagerFactory")
  public LocalContainerEntityManagerFactoryBean mainEntityManagerFactory(
      EntityManagerFactoryBuilder builder, @Qualifier("mainDataSource") DataSource dataSource,
      MainJpaProperties mainJpaProperties) {
    LocalContainerEntityManagerFactoryBean factory = builder
        .dataSource(dataSource)
        .packages("vn.com.viettel.vds.model.main")
        .persistenceUnit("dbMain")
        .build();
    factory.setJpaPropertyMap(mainJpaProperties.getProperties());
    return factory;
  }

  @Primary
  @Bean(name = "mainTransactionManager")
  public PlatformTransactionManager mainTransactionManager(
      @Qualifier("mainEntityManagerFactory") EntityManagerFactory entityManagerFactory) {
    return new JpaTransactionManager(entityManagerFactory);
  }

}

package vn.com.viettel.vds.config.database;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.orm.jpa.vendor.Database;

@ConfigurationProperties(prefix = "app.datasource.main.jpa")
public class MainJpaProperties {

	/**
	 * Additional native properties to set on the JPA provider.
	 */
	private Map<String, String> properties = new HashMap<>();

	/**
	 * Mapping resources (equivalent to "mapping-file" entries in persistence.xml).
	 */
	private final List<String> mappingResources = new ArrayList<>();

	/**
	 * Name of the target database to operate on, auto-detected by default. Can be
	 * alternatively set using the "Database" enum.
	 */
	private String databasePlatform;

	/**
	 * Target database to operate on, auto-detected by default. Can be alternatively set
	 * using the "databasePlatform" property.
	 */
	private Database database;

	/**
	 * Whether to initialize the schema on startup.
	 */
	private boolean generateDdl = false;

	/**
	 * Whether to enable logging of SQL statements.
	 */
	private boolean showSql = false;

	/**
	 * Register OpenEntityManagerInViewInterceptor. Binds a JPA EntityManager to the
	 * thread for the entire processing of the request.
	 */
	private Boolean openInView;

	public Map<String, String> getProperties() {
		return this.properties;
	}

	public void setProperties(Map<String, String> properties) {
		this.properties = properties;
	}

	public List<String> getMappingResources() {
		return this.mappingResources;
	}

	public String getDatabasePlatform() {
		return this.databasePlatform;
	}

	public void setDatabasePlatform(String databasePlatform) {
		this.databasePlatform = databasePlatform;
	}

	public Database getDatabase() {
		return this.database;
	}

	public void setDatabase(Database database) {
		this.database = database;
	}

	public boolean isGenerateDdl() {
		return this.generateDdl;
	}

	public void setGenerateDdl(boolean generateDdl) {
		this.generateDdl = generateDdl;
	}

	public boolean isShowSql() {
		return this.showSql;
	}

	public void setShowSql(boolean showSql) {
		this.showSql = showSql;
	}

	public Boolean getOpenInView() {
		return this.openInView;
	}

	public void setOpenInView(Boolean openInView) {
		this.openInView = openInView;
	}

}

