package vn.com.viettel.vds.config.formatdate;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeParseException;
import lombok.extern.slf4j.Slf4j;
import vn.com.viettel.vds.util.common.DateTimeUtils;

/**
 * Thực hiện parse data json request to localDateTime
 *
 * @author HoangTD5
 * @version 0.1
 * @date 8/26/2020
 */
@Slf4j
public class LocalDateTimeDeserializer extends JsonDeserializer<LocalDateTime> {

  public static final String YYYY_MM_DD_HH_MM_SS = "yyyy-MM-dd HH:mm:ss";
  public static final String YYYY_MM_DD_T_HH_MM_SS = "yyyy-MM-dd'T'HH:mm:ss";
  public static final String YYYY_MM_DD_FULL = "yyyy-MM-dd'T'HH:mm:ss.SSSZ";

  @Override
  public LocalDateTime deserialize(JsonParser jsonParser,
      DeserializationContext deserializationContext) throws IOException {
    String str = jsonParser.getText();
    try {
      return DateTimeUtils.convertStringToLocalDateTime(str, YYYY_MM_DD_T_HH_MM_SS);
    } catch (DateTimeParseException e) {
      return deserialize(str);
    }
  }

  private LocalDateTime deserialize(String str) {
    try {
      return DateTimeUtils.convertStringToLocalDateTime(str, YYYY_MM_DD_HH_MM_SS);
    } catch (DateTimeParseException e) {
      return deserialize2(str);
    }
  }

  private LocalDateTime deserialize2(String str) {
    try {
      return DateTimeUtils.convertStringToLocalDateTime(str, YYYY_MM_DD_FULL);
    } catch (DateTimeParseException e) {
      return null;
    }
  }
}

package vn.com.viettel.vds.config.formatdate;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.JsonSerializer;
import com.fasterxml.jackson.databind.SerializerProvider;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeParseException;
import lombok.extern.slf4j.Slf4j;
import vn.com.viettel.vds.util.common.DateTimeUtils;

/**
 * Thực hiện parse data response to string json
 *
 * @author HoangTD5
 * @version 0.1
 * @date 8/26/2020
 */
@Slf4j
public class LocalDateTimeSerializer extends JsonSerializer<LocalDateTime> {

  public static final String YYYY_MM_DD_T_HH_MM_SS = "yyyy-MM-dd'T'HH:mm:ss";

  @Override
  public void serialize(LocalDateTime localDateTime, JsonGenerator jsonGenerator,
      SerializerProvider serializerProvider) throws IOException {
    try {
      String result = DateTimeUtils.localDateTimeToString(localDateTime, YYYY_MM_DD_T_HH_MM_SS);
      jsonGenerator.writeString(result);
    } catch (DateTimeParseException e) {
      log.error(e.getMessage(), e);
      jsonGenerator.writeString("");
    }
  }
}

package vn.com.viettel.vds.config.kafka;

import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
