import org.springframework.kafka.core.DefaultKafkaConsumerFactory;
import org.springframework.kafka.listener.ContainerProperties;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

@Configuration
@EnableKafka
@EnableConfigurationProperties(MultiKafkaProperties.class)
public class KafkaConsumerConfig {

    private final MultiKafkaProperties multiKafkaProperties;

    public KafkaConsumerConfig(MultiKafkaProperties multiKafkaProperties) {
        this.multiKafkaProperties = multiKafkaProperties;
    }

    /**
     * Cấu hình mặc định cho consumer
     */
    private Map<String, Object> defaultConsumerProps(MultiKafkaProperties.ConsumerConfig consumer) {
        Map<String, Object> props = new HashMap<>();

        // Deserialize
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);

        // Quản lý offset thủ công
        props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, consumer.isEnableAutoCommit());
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, consumer.getAutoOffsetReset());

        // Poll / heartbeat
        if (Objects.nonNull(consumer.getMaxPollIntervalMs())) {
            props.put(ConsumerConfig.MAX_POLL_INTERVAL_MS_CONFIG, consumer.getMaxPollIntervalMs());
        }
        if (Objects.nonNull(consumer.getMaxPollRecords())) {
            props.put(ConsumerConfig.MAX_POLL_RECORDS_CONFIG, consumer.getMaxPollRecords());
        }
        if (Objects.nonNull(consumer.getSessionTimeoutMs())) {
            props.put(ConsumerConfig.SESSION_TIMEOUT_MS_CONFIG, consumer.getSessionTimeoutMs());
        }
        if (Objects.nonNull(consumer.getHeartbeatIntervalMs())) {
            props.put(ConsumerConfig.HEARTBEAT_INTERVAL_MS_CONFIG, consumer.getHeartbeatIntervalMs());
        }

        // Retry network / reconnect
        if (Objects.nonNull(consumer.getReconnectBackoffMs())) {
            props.put(ConsumerConfig.RECONNECT_BACKOFF_MS_CONFIG, consumer.getReconnectBackoffMs());
        }
        if (Objects.nonNull(consumer.getReconnectBackoffMaxMs())) {
            props.put(ConsumerConfig.RECONNECT_BACKOFF_MAX_MS_CONFIG, consumer.getReconnectBackoffMaxMs());
        }
        if (Objects.nonNull(consumer.getRetryBackoffMs())) {
            props.put(ConsumerConfig.RETRY_BACKOFF_MS_CONFIG, consumer.getRetryBackoffMs());
        }

        // Tăng độ an toàn
        if (Objects.nonNull(consumer.getFetchMaxWaitMs())) {
            props.put(ConsumerConfig.FETCH_MAX_WAIT_MS_CONFIG, consumer.getFetchMaxWaitMs());
        }
        if (Objects.nonNull(consumer.getFetchMinBytes())) {
            props.put(ConsumerConfig.FETCH_MIN_BYTES_CONFIG, consumer.getFetchMinBytes());
        }

        return props;
    }

    /**
     * Build properties cho từng cluster
     */
    private Map<String, Object> buildConsumerProps(MultiKafkaProperties.ClusterConfig cluster) {

        Map<String, Object> props = new HashMap<>(defaultConsumerProps(cluster.getConsumer()));
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, cluster.getBootstrapServers());
        props.put(ConsumerConfig.GROUP_ID_CONFIG, cluster.getGroupId());
        if (cluster.getAuth() != null && cluster.getAuth().isEnabled()) {
            props.putAll(buildAuthProps(cluster.getAuth()));
        }
        return props;
    }

    /**
     * Build Auth nếu có
     */
    private Map<String, Object> buildAuthProps(MultiKafkaProperties.AuthConfig auth) {
        Map<String, Object> authProps = new HashMap<>();
        authProps.put("security.protocol", auth.getProtocol());
        authProps.put("sasl.mechanism", auth.getMechanism());
        authProps.put("sasl.jaas.config",
                String.format("org.apache.kafka.common.security.plain.PlainLoginModule required username=\"%s\" password=\"%s\";",
                        auth.getUsername(), auth.getPassword()));
        return authProps;
    }

    /**
     * Build KafkaListener factory từ ConsumerFactory
     */
    private ConcurrentKafkaListenerContainerFactory<String, String> buildFactory(ConsumerFactory<String, String> consumerFactory, MultiKafkaProperties.ClusterConfig clusterConfig) {
        ConcurrentKafkaListenerContainerFactory<String, String> factory = new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory);
        if (Objects.nonNull(clusterConfig.getAckMode())) {
            factory.getContainerProperties().setAckMode(ContainerProperties.AckMode.RECORD);
        }
        return factory;
    }

    /**
     * Factory cluster policyService
     */
    @Bean
    @ConditionalOnProperty(name = "spring.kafka.clusters.policyService.enabled", havingValue = "true")
    public ConcurrentKafkaListenerContainerFactory<String, String> clusterPolicyFactory() {
        MultiKafkaProperties.ClusterConfig cluster = multiKafkaProperties.getClusters().get("policyService");
        ConsumerFactory<String, String> consumerFactory = new DefaultKafkaConsumerFactory<>(buildConsumerProps(cluster));
        return buildFactory(consumerFactory, cluster);
    }

    /**
     * Factory cluster tranHis
     */
    @Bean
    @ConditionalOnProperty(name = "spring.kafka.clusters.tranHis.enabled", havingValue = "true")
    public ConcurrentKafkaListenerContainerFactory<String, String> clusterTranHisFactory() {
        MultiKafkaProperties.ClusterConfig cluster = multiKafkaProperties.getClusters().get("tranHis");
        ConsumerFactory<String, String> consumerFactory = new DefaultKafkaConsumerFactory<>(buildConsumerProps(cluster));
        return buildFactory(consumerFactory, cluster);
    }
}

