package vn.com.viettel.vds.config.locale;

import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import javax.servlet.http.HttpServletRequest;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import org.springframework.web.servlet.i18n.AcceptHeaderLocaleResolver;
import org.springframework.web.servlet.i18n.LocaleChangeInterceptor;

@Configuration
@SuppressWarnings("java:S1874")
public class CustomLocaleResolver
    extends AcceptHeaderLocaleResolver
    implements WebMvcConfigurer {

  private static final List<Locale> LOCALES = Arrays.asList(
      new Locale("en"),
      new Locale("vi"));

  @Override
  public Locale resolveLocale(HttpServletRequest request) {
    String headerLang = request.getHeader("Accept-Language");
    return headerLang == null || headerLang.isEmpty()
        ? Locale.getDefault()
        : Locale.lookup(Locale.LanguageRange.parse(headerLang), LOCALES);
  }

  /**
   * @param registry
   */
  @Override
  public void addInterceptors(InterceptorRegistry registry) {
    LocaleChangeInterceptor localeChangeInterceptor = new LocaleChangeInterceptor();
    localeChangeInterceptor.setParamName("lang");
    registry.addInterceptor(localeChangeInterceptor);
  }

}

package vn.com.viettel.vds.config.redis;

import lombok.extern.slf4j.Slf4j;
import org.springframework.cache.Cache;
import org.springframework.cache.interceptor.CacheErrorHandler;

/**
 * @author SonNV41
 * @version v1
 * @date 4/22/2022
 */
@Slf4j
public class RedisCacheErrorHandler implements CacheErrorHandler {

    @Override
    public void handleCacheGetError(RuntimeException exception, Cache cache, Object key) {
        handleTimeOutException(exception);
        log.info("Unable to get into cache {}:{}", cache.getName(), exception.getMessage());
    }

    @Override
    public void handleCachePutError(
        RuntimeException exception, Cache cache, Object key, Object value) {
        handleTimeOutException(exception);
        log.info("Unable to put into cache {}:{}", cache.getName(), exception.getMessage());
    }

    @Override
    public void handleCacheEvictError(RuntimeException exception, Cache cache, Object key) {
        handleTimeOutException(exception);
        log.info("Unable to evict cache {}:{}:{}", cache.getName(), key, exception.getMessage());
    }

    @Override
    public void handleCacheClearError(RuntimeException exception, Cache cache) {
        handleTimeOutException(exception);
        log.info("Unable to clean cache {}:{}", cache.getName(), exception.getMessage());
    }

    /**
     * We handle redis connection timeout exception , if the exception is handled then it is treated
     * as a cache miss and gets the data from actual storage
     *
     * @param e
     */
    private void handleTimeOutException(RuntimeException e) {
        log.error(e.getMessage(), e);
    }
}

package vn.com.viettel.vds.config.redis;

import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.redisson.Redisson;
import org.redisson.api.RedissonClient;
import org.redisson.config.Config;
import org.redisson.spring.data.connection.RedissonConnectionFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.cache.CacheManager;
import org.springframework.cache.annotation.CachingConfigurerSupport;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.cache.interceptor.CacheErrorHandler;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.cache.RedisCacheConfiguration;
import org.springframework.data.redis.cache.RedisCacheManager;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.JdkSerializationRedisSerializer;
import org.springframework.data.redis.serializer.RedisSerializationContext.SerializationPair;
import org.springframework.data.redis.serializer.RedisSerializer;
import vn.com.viettel.vds.constant.Constants;

import java.time.Duration;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

/**
 * @author SonNV41
 * @version v1
 * @date 4/22/2022
 */
@Configuration
@EnableCaching
@ConditionalOnProperty(value = "app.cache.redisson.enable", havingValue = "true")
@EnableConfigurationProperties(RedissonClusterConfigurationProperties.class)
@Slf4j
public class RedissonCacheConfig extends CachingConfigurerSupport {

    @Value("${app.cache.redisson.clientName}")
    private String applicationShortName;

    public SerializationPair<Object> getJdkSerialization() {
        ClassLoader loader = Thread.currentThread().getContextClassLoader();
        JdkSerializationRedisSerializer jdkSerializer = new JdkSerializationRedisSerializer(loader);
        return SerializationPair.fromSerializer(jdkSerializer);
    }

    public RedisCacheConfiguration createDefaultCacheConfiguration(long ttl) {
        return RedisCacheConfiguration.defaultCacheConfig()
            .serializeValuesWith(getJdkSerialization())
            .computePrefixWith(cacheName -> {
                String prefix = applicationShortName + "::";
                if (!StringUtils.isEmpty(cacheName)) {
                    prefix += cacheName + "::";
                }
                return prefix;
            })
            .entryTtl(Duration.ofMillis(ttl));
    }

    @Bean("redisStringTemplate")
    public RedisTemplate<String, String> redisStringTemplate(RedissonConnectionFactory cf) {
        RedisTemplate<String, String> redisTemplate = new RedisTemplate<>();
        redisTemplate.setKeySerializer(RedisSerializer.string());
        redisTemplate.setHashKeySerializer(RedisSerializer.string());
        redisTemplate.setConnectionFactory(cf);
        return redisTemplate;
    }

    @Bean("redisObjectTemplate")
    public RedisTemplate<String, Object> redisTemplate(RedissonConnectionFactory cf) {
        RedisTemplate<String, Object> redisTemplate = new RedisTemplate<>();
        redisTemplate.setKeySerializer(RedisSerializer.string());
        redisTemplate.setHashKeySerializer(RedisSerializer.string());
        redisTemplate.setConnectionFactory(cf);
        return redisTemplate;
    }

    @Bean(destroyMethod = "shutdown")
    public RedissonClient redisson(
        RedissonClusterConfigurationProperties prop) {
        Config config = new Config();
        config.useClusterServers()
            .setCheckSlotsCoverage(prop.isCheckSlotsCoverage())
            .setIdleConnectionTimeout(prop.getIdleConnectTimeout())
            .setConnectTimeout(prop.getConnectTimeout())
            .setTimeout(prop.getTimeout())
            .setRetryAttempts(prop.getRetryAttempts())
            .setRetryInterval(prop.getRetryInterval())
            .setFailedSlaveReconnectionInterval(prop.getFailedSlaveReconnectionInterval())
            .setFailedSlaveCheckInterval(prop.getFailedSlaveCheckInterval())
            .setSubscriptionsPerConnection(prop.getSubscriptionsPerConnection())
            .setClientName(prop.getClientName())
            .setSubscriptionConnectionPoolSize(prop.getSubscriptionConnectionPoolSize())
            .setSlaveConnectionMinimumIdleSize(prop.getSlaveConnectionMinimumIdleSize())
            .setSlaveConnectionPoolSize(prop.getSlaveConnectionPoolSize())
            .setMasterConnectionMinimumIdleSize(prop.getMasterConnectionMinimumIdleSize())
            .setMasterConnectionPoolSize(prop.getMasterConnectionPoolSize())
            .setScanInterval(prop.getScanInterval())
            .setPingConnectionInterval(prop.getPingConnectionInterval())
            .setKeepAlive(prop.isKeepAlive())
            .setTcpNoDelay(prop.isTcpNoDelay())
            .setNodeAddresses(Arrays.asList(prop.getNodeAddresses().split(",")));
        if (StringUtils.isNotBlank(prop.getPassword())) {
            config.useClusterServers().setPassword(prop.getPassword());
        }
        return Redisson.create(config);
    }

    @Bean
    public RedissonConnectionFactory redissonConnectionFactory(RedissonClient redisson) {

        return new RedissonConnectionFactory(redisson);
    }

    @Bean(name = Constants.CacheManagerName.POLICY_PAYMENT_CACHE_MANAGER)
    public CacheManager redisCacheManager(
        RedissonConnectionFactory redissonConnectionFactory,
        RedissonClusterConfigurationProperties properties) {
        Map<String, RedisCacheConfiguration> config = new HashMap<>();
        for (Map.Entry<String, Long> cachesWithTtl : properties.getCacheExpirations()
            .entrySet()) {
            config.put(cachesWithTtl.getKey(),
                createDefaultCacheConfiguration(cachesWithTtl.getValue()));
        }
        return RedisCacheManager
            .builder(redissonConnectionFactory)
            .cacheDefaults(createDefaultCacheConfiguration(properties.getTtl()))
            .withInitialCacheConfigurations(config).build();
    }

    @Override
    public CacheErrorHandler errorHandler() {
        return new RedisCacheErrorHandler();
    }
}

