package vn.com.viettel.vds.constant.enums;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonValue;
import lombok.AllArgsConstructor;
import lombok.Getter;

import java.util.HashMap;
import java.util.Map;

@Getter
@AllArgsConstructor
public enum TransactionStatusEnum {
    // that bai
    UNKNOWN(null, null),
    SUCCESS("SUCCESS", "Thành công"),
    TIMEOUT("TIMEOUT", "Timeout");

    @JsonValue
    private final String value;

    private final String text;

    private static final Map<String, TransactionStatusEnum> TRANSACTION_STATUS_ENUM_MAP = new HashMap<>();

    static {
        for (TransactionStatusEnum status : TransactionStatusEnum.values()) {
            TRANSACTION_STATUS_ENUM_MAP.put(status.value, status);
        }
    }

    @JsonCreator
    public static TransactionStatusEnum fromValue(String value) {
        if (value == null) {
            return TransactionStatusEnum.UNKNOWN;
        }
        TransactionStatusEnum transactionStatusEnum = TRANSACTION_STATUS_ENUM_MAP.get(value);
        if (transactionStatusEnum == null) {
            return TransactionStatusEnum.UNKNOWN;
        }
        return transactionStatusEnum;
    }
}

