package vn.com.viettel.vds.consumer;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.stereotype.Component;
import vn.com.viettel.vds.client.PolicyManagementServiceClient;
import vn.com.viettel.vds.constant.Constants;
import vn.com.viettel.vds.constant.enums.TransactionStatusEnum;
import vn.com.viettel.vds.domain.dto.CustomerDTO;
import vn.com.viettel.vds.domain.dto.CustomerPaymentLimitTransDTO;
import vn.com.viettel.vds.domain.input.AccumulateLimitInputDTO;
import vn.com.viettel.vds.domain.input.AccumulatePolicyLimitDTO;
import vn.com.viettel.vds.service.main.CustomerPaymentLimitService;
import vn.com.viettel.vds.service.main.CustomerPaymentLimitTransService;
import vn.com.viettel.vds.service.main.RedisService;
import vn.com.viettel.vds.util.common.DataUtils;
import vn.com.viettel.vds.util.common.TransactionStatusUtils;

import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;

@Slf4j
@Component
@SuppressWarnings({"java:S3776", "S1871", "java:S6541", "java:S1871", "java:S112", "java:S2142"})
public class CustomerPaymentLimitConsumer {
    @Autowired
    private PolicyManagementServiceClient policyManagementServiceClient;

    private static final String AUTH = "AUTH";

    @Autowired
    private CustomerPaymentLimitService limitService;

    @Autowired
    private TransactionStatusUtils transactionStatus;

    @Autowired
    private CustomerPaymentLimitTransService transService;

    @Autowired
    private RedisService redisService;

    @Autowired
    private ObjectMapper objectMapper;

    @KafkaListener(autoStartup = "${spring.kafka.clusters.policyService.consumer.topics.v1_policy_customer_limit_trans.autoStartup}",
            topics = "${spring.kafka.clusters.policyService.consumer.topics.v1_policy_customer_limit_trans.value}",
            groupId = "${spring.kafka.clusters.policyService.groupId}",
            containerFactory = "clusterPolicyFactory")
    public void listenerCustomerPaymentLimit(@Payload String message) {
        String keyLock = "";
        try {
            log.info("listenerCustomerPaymentLimit From message {}", message);
            List<CustomerPaymentLimitTransDTO> listMsg = Arrays.asList(DataUtils.OBJECT_MAPPER_CUSTOM.readValue(message, CustomerPaymentLimitTransDTO[].class));

            Set<String> requestIds = listMsg.stream()
                    .filter(Objects::nonNull)
                    .map(CustomerPaymentLimitTransDTO::getRequestId)
                    .sorted(Comparator.reverseOrder()) // Sắp xếp theo thứ tự ngược
                    .collect(Collectors.toCollection(LinkedHashSet::new)); // Thu thập vào LinkedHashSet

            keyLock = "POLICY_PAYMENT_LIMIT".concat("|").concat(String.valueOf(requestIds));
            Boolean isLock = redisService.lock(keyLock, keyLock, 10, TimeUnit.SECONDS);
            if (Boolean.FALSE.equals(isLock)) return;

            Map<String, Integer> quantity = new HashMap<>();
            for (CustomerPaymentLimitTransDTO msg : listMsg) {
                msg.setLitmitType("ADD");
                limitService.savePaymentLimit(msg, quantity, null);
            }
        } catch (Exception ex) {
            log.error("listenerAuthAccumulate Exception {} message {}", ex.getMessage(), message, ex);
        }
    }

    @KafkaListener(autoStartup = "${spring.kafka.clusters.policyService.consumer.topics.v1_policy_customer_payment.autoStartup}",
            topics = "${spring.kafka.clusters.policyService.consumer.topics.v1_policy_customer_payment.value}",
            groupId = "${spring.kafka.clusters.policyService.groupId}-limit",
            containerFactory = "clusterPolicyFactory")
    public void listenerUpdateCustomerPaymentLimit(@Payload String message) {
        try {
            log.info("listenerUpdateCustomerPaymentLimit From message {}", message);
            JsonNode node = objectMapper.readTree(message);
            List<CustomerPaymentLimitTransDTO> listMsg =
                    node.isArray()
                            ? Arrays.asList(DataUtils.OBJECT_MAPPER_CUSTOM.readValue(message, CustomerPaymentLimitTransDTO[].class))
                            : Collections.singletonList(DataUtils.OBJECT_MAPPER_CUSTOM.readValue(message, CustomerPaymentLimitTransDTO.class));
            updateCustomerPaymentLimitHandler(listMsg);
        } catch (Exception ex) {
            log.error("listenerUpdateCustomerPaymentLimit Exception {} message {}", ex.getMessage(), message, ex);
        }
    }

    public void updateCustomerPaymentLimitHandler(List<CustomerPaymentLimitTransDTO> listMsg) {
        String keyLock = "";
        try {
            Map<String, Integer> quantity = new HashMap<>();
            Set<String> requestIds = listMsg.stream()
                    .filter(Objects::nonNull)
                    .map(CustomerPaymentLimitTransDTO::getRequestId)
                    .sorted(Comparator.reverseOrder())
                    .collect(Collectors.toCollection(LinkedHashSet::new));
            keyLock = "POLICY_PAYMENT_LIMIT".concat("|").concat(String.valueOf(requestIds));
            Boolean isLock = redisService.lock(keyLock, keyLock, 10, TimeUnit.SECONDS);
            if (Boolean.FALSE.equals(isLock)) {
                tryLock(keyLock, keyLock, 10, TimeUnit.SECONDS);
            }

            Map<String, CustomerPaymentLimitTransDTO> mapTrans = transService.findByRequestIdInAndRequestMti(requestIds, "NOT_AUTH").stream().collect(Collectors.toMap(CustomerPaymentLimitTransDTO::getRequestId, transDTO -> transDTO));

            if (mapTrans == null || mapTrans.isEmpty()) {
                log.info("return updateCustomerPaymentLimitHandler CustomerPaymentLimitTrans isEmpty");
                return;
            }

            Map<String, Boolean> mapAllFalse = new HashMap<>();
            Map<String, Boolean> mapSenderAllFalse = new HashMap<>();
            Map<String, Boolean> mapReceiverAllFalse = new HashMap<>();

            //group dich vu va nguon tien, check trang thai gd false all thi giam tru so luong gd cua dich vu
            Map<String, List<CustomerPaymentLimitTransDTO>> listMap = listMsg.stream().collect(Collectors.groupingBy(msg -> DataUtils.groupingByKeyLimitTrans(msg)));
            listMap.forEach((key, value) ->
                    mapAllFalse.put(key, value.stream().allMatch(f -> TransactionStatusEnum.UNKNOWN
                            .equals(transactionStatus.getErrorCode(f.getErrorCode(), f.getCorrectCode())))));

            listMsg.forEach(val -> {
                val.setSenderJson(Objects.nonNull(mapTrans.get(val.getRequestId())) ? mapTrans.get(val.getRequestId()).getSenderJson() : null);
                if (Boolean.TRUE.equals(Objects.nonNull(val.getSenderJson()))) {
                    try {
                        val.setSender(objectMapper.readValue(val.getSenderJson(), CustomerDTO.class));
                    } catch (JsonProcessingException e) {
                        log.info("Sender parse json fail {}", e.getMessage());
                    }
                }
                val.setReceiverJson(Objects.nonNull(mapTrans.get(val.getRequestId())) ? mapTrans.get(val.getRequestId()).getReceiverJson() : null);
                if (Boolean.TRUE.equals(Objects.nonNull(val.getReceiverJson()))) {
                    try {
                        val.setReceiver(objectMapper.readValue(val.getReceiverJson(), CustomerDTO.class));
                    } catch (JsonProcessingException e) {
                        log.info("Receiver parse json fail {}", e.getMessage());
                    }
                }
            });

            //group cac dich vu cung chinh sach, check trang thai gd false all thi giam tru so luong gd cua chinh sach
            Map<String, List<CustomerPaymentLimitTransDTO>> listMapSender = listMsg.stream().filter(f -> Objects.nonNull(f.getSender()) && Objects.nonNull(f.getSender().getId())).collect(Collectors.groupingBy(msg -> msg.getSender().getPolicyLimit().stream().map(a -> a.getCode()).collect(Collectors.joining(","))));
            listMapSender.forEach((key, value) ->
                    mapSenderAllFalse.put(key, value.stream().allMatch(f -> TransactionStatusEnum.UNKNOWN
                            .equals(transactionStatus.getErrorCode(f.getErrorCode(), f.getCorrectCode())))));
            Map<String, List<CustomerPaymentLimitTransDTO>> listMapReceiver = listMsg.stream().filter(f -> Objects.nonNull(f.getReceiver()) && Objects.nonNull(f.getReceiver().getId())).collect(Collectors.groupingBy(msg -> msg.getReceiver().getPolicyLimit().stream().map(a -> a.getCode()).collect(Collectors.joining(","))));
            listMapReceiver.forEach((key, value) ->
                    mapReceiverAllFalse.put(key, value.stream().allMatch(f -> TransactionStatusEnum.UNKNOWN
                            .equals(transactionStatus.getErrorCode(f.getErrorCode(), f.getCorrectCode())))));

            for (CustomerPaymentLimitTransDTO msg : listMsg) {
                msg.setLitmitType("UPDATE");
                msg.setMapAllFalse(mapAllFalse);
                msg.setMapSenderAllFalse(mapSenderAllFalse);
                msg.setMapReceiverAllFalse(mapReceiverAllFalse);
                limitService.savePaymentLimit(msg, quantity, mapTrans.get(msg.getRequestId()));
            }

        } catch (Exception ex) {
            throw new RuntimeException(ex);
        } finally {
            redisService.release(keyLock);
        }
    }

    @KafkaListener(autoStartup = "${spring.kafka.clusters.policyService.consumer.topics.v1_policy_auth_accumulate.autoStartup}",
            topics = "${spring.kafka.clusters.policyService.consumer.topics.v1_policy_auth_accumulate.value}",
            groupId = "${spring.kafka.clusters.policyService.groupId}",
            containerFactory = "clusterPolicyFactory")
    public void listenerAuthAccumulate(@Payload String message) {
        try {
            log.info("listenerAuthAccumulate From message {}", message);
            CustomerPaymentLimitTransDTO msg = DataUtils.OBJECT_MAPPER_CUSTOM.readValue(message, CustomerPaymentLimitTransDTO.class);
            if (Constants.ERROR_CODE_SUCCESS.equals(getErrorCode(msg.getErrorCode(), msg.getCorrectCode()))) {
                msg.setAuth(AUTH);
                if (Boolean.TRUE.equals(DataUtils.nullOrEmpty(msg.getRequestType()))) {
                    msg.setRequestType("ADD");
                }
                List<AccumulatePolicyLimitDTO> limitDTOList = policyManagementServiceClient.availableListLimit(msg);
                if (Boolean.TRUE.equals(DataUtils.notNullOrEmpty(limitDTOList))) {
                    limitService.saveAuthPaymentLimit(AccumulateLimitInputDTO.builder()
                            .policyLimit(limitDTOList)
                            .customerPayment(msg)
                            .build());
                }
            }
        } catch (Exception ex) {
            log.error("listenerAuthAccumulate Exception {} message {}", ex.getMessage(), message, ex);
        }
    }

    private String getErrorCode(String errorCode, String correctCode) {
        if (Boolean.TRUE.equals(DataUtils.notNullOrEmpty(correctCode))) {
            return correctCode;
        }
        return errorCode;
    }

    private void tryLock(String keyLog, String value, long timeout, TimeUnit unit) throws InterruptedException {
        boolean tryLock;
        do {
            tryLock = redisService.lock(keyLog, value, timeout, unit);
            Thread.sleep(50);
        } while (!tryLock);
        // TryLock thành công rồi mới cho phép xử lý tiếp.
    }
}

